    fun getWesternIdioms(targetLang: String, nativeLang: String): List<PhraseItem> {
        val list = when (targetLang.lowercase()) {
            "es" -> spanishIdioms
            "fr" -> frenchIdioms
            "de" -> germanIdioms
            "en" -> englishIdioms
            "it" -> italianIdioms
            "pt" -> portugueseIdioms
            else -> emptyList()
        }
        return list
    }

